insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '1e031ed5-9788-5d0e-abfd-03b8d55d6ce0', e.id, 'IN', (select id from public.content_components where code = 'IN.P6'), 'qa_passed', 'cefr_part', '{"title":"Why we forget what we study","text":"Most students have had this experience: you study for hours the night before a test, you feel ready, and a week later you can hardly remember anything. This is not because you are lazy or because your memory is bad. It is simply how the brain works.\n\nMore than a hundred years ago, the German psychologist Hermann Ebbinghaus tested his own memory by learning lists of invented words. He discovered that we forget new information very quickly at first, and then more slowly. He called this pattern the \"forgetting curve\".\n\nThe good news is that the curve can be changed. Every time we try to remember something, especially just before we forget it, the memory becomes stronger and lasts longer. This is why reviewing material several times over days or weeks works much better than reading it many times in one evening. Testing yourself is also more effective than simply rereading your notes, because it forces your brain to bring the information back.\n\nOf course, these techniques require planning. You cannot leave everything until the last night. But students who space out their studying usually find that they need less total time, and that they remember more months later.","svg":null,"table":null}'::jsonb, 'According to the first paragraph, why do students forget what they studied the night before?', '[{"label":"A","text":"Because tests are always too difficult.","is_correct":false,"distractor_type":"Inventa una causa externa.","explanation_feedback":"Incorrecta. El texto no culpa a la dificultad de los exámenes."},{"label":"B","text":"Because they are lazy and don''t study enough.","is_correct":false,"distractor_type":"Toma como causa lo que el texto niega.","explanation_feedback":"Incorrecta. El texto descarta explícitamente la pereza."},{"label":"C","text":"Because they have a bad memory.","is_correct":false,"distractor_type":"Toma como causa lo que el texto niega.","explanation_feedback":"Incorrecta. El texto dice que no es por tener mala memoria."},{"label":"D","text":"Because forgetting is a normal function of the brain.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El texto dice que no es por pereza ni mala memoria: «It is simply how the brain works»."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 90, 'original_generated'
from public.evidences e where e.code = 'IN.E6'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'af47a1d7-b3ee-54df-8511-9cbf8b085051', e.id, 'IN', (select id from public.content_components where code = 'IN.P6'), 'qa_passed', 'cefr_part', '{"title":"Why we forget what we study","text":"Most students have had this experience: you study for hours the night before a test, you feel ready, and a week later you can hardly remember anything. This is not because you are lazy or because your memory is bad. It is simply how the brain works.\n\nMore than a hundred years ago, the German psychologist Hermann Ebbinghaus tested his own memory by learning lists of invented words. He discovered that we forget new information very quickly at first, and then more slowly. He called this pattern the \"forgetting curve\".\n\nThe good news is that the curve can be changed. Every time we try to remember something, especially just before we forget it, the memory becomes stronger and lasts longer. This is why reviewing material several times over days or weeks works much better than reading it many times in one evening. Testing yourself is also more effective than simply rereading your notes, because it forces your brain to bring the information back.\n\nOf course, these techniques require planning. You cannot leave everything until the last night. But students who space out their studying usually find that they need less total time, and that they remember more months later.","svg":null,"table":null}'::jsonb, 'What did Ebbinghaus discover?', '[{"label":"A","text":"We forget everything after exactly one week.","is_correct":false,"distractor_type":"Toma el ejemplo inicial como ley científica.","explanation_feedback":"Incorrecta. La semana es un ejemplo de la experiencia estudiantil; la curva no fija un plazo exacto."},{"label":"B","text":"German students remember more than others.","is_correct":false,"distractor_type":"Relaciona su nacionalidad con el hallazgo.","explanation_feedback":"Incorrecta. El texto no compara estudiantes por país."},{"label":"C","text":"We lose new information fast at first and then more slowly.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Descubrió que se olvida muy rápido al principio y luego más despacio."},{"label":"D","text":"Invented words are easier to remember than real ones.","is_correct":false,"distractor_type":"Confunde el método (palabras inventadas) con el hallazgo.","explanation_feedback":"Incorrecta. Usó palabras inventadas para probar su memoria, pero eso no es lo que descubrió."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 90, 'original_generated'
