select '0eaf9272-72d3-5500-a995-b2463b4f4021', e.id, 'IN', (select id from public.content_components where code = 'IN.P6'), 'qa_passed', 'cefr_part', '{"title":"Why we forget what we study","text":"Most students have had this experience: you study for hours the night before a test, you feel ready, and a week later you can hardly remember anything. This is not because you are lazy or because your memory is bad. It is simply how the brain works.\n\nMore than a hundred years ago, the German psychologist Hermann Ebbinghaus tested his own memory by learning lists of invented words. He discovered that we forget new information very quickly at first, and then more slowly. He called this pattern the \"forgetting curve\".\n\nThe good news is that the curve can be changed. Every time we try to remember something, especially just before we forget it, the memory becomes stronger and lasts longer. This is why reviewing material several times over days or weeks works much better than reading it many times in one evening. Testing yourself is also more effective than simply rereading your notes, because it forces your brain to bring the information back.\n\nOf course, these techniques require planning. You cannot leave everything until the last night. But students who space out their studying usually find that they need less total time, and that they remember more months later.","svg":null,"table":null}'::jsonb, 'What is the writer''s main purpose?', '[{"label":"A","text":"To prove that tests are not necessary.","is_correct":false,"distractor_type":"Contradice la valoración de autoevaluarse.","explanation_feedback":"Incorrecta. El texto valora ponerse a prueba como técnica de estudio."},{"label":"B","text":"To tell the life story of Hermann Ebbinghaus.","is_correct":false,"distractor_type":"Toma un detalle como propósito.","explanation_feedback":"Incorrecta. Ebbinghaus aparece para explicar la curva, no para contar su vida."},{"label":"C","text":"To explain why spaced practice helps students remember.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El texto explica la curva del olvido y cómo repasar espaciadamente ayuda a recordar."},{"label":"D","text":"To criticise students who study at night.","is_correct":false,"distractor_type":"Exagera el tono del texto.","explanation_feedback":"Incorrecta. El texto no culpa a los estudiantes; explica cómo funciona la memoria."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 90, 'original_generated'
from public.evidences e where e.code = 'IN.E6'
