insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '6b7c5eba-a9a0-5ce4-955d-566a2ebd67a8', e.id, 'IN', (select id from public.content_components where code = 'IN.P6'), 'qa_passed', 'cefr_part', '{"title":"Cooler cities","text":"On a sunny afternoon, the centre of a large city can be several degrees hotter than the countryside around it. Scientists call this an \"urban heat island\". It happens because materials like concrete and asphalt absorb heat during the day and release it slowly at night. Cars, air conditioners and factories add even more heat.\n\nThis is not just a question of comfort. Very high temperatures can be dangerous for older people and small children, and they increase the amount of electricity a city uses. In some places, hot nights also make the air more polluted.\n\nCities around the world are trying different solutions. Medellín, for example, created a network of \"green corridors\" by planting trees and plants along roads and streams. Officials say temperatures in some of those areas have fallen by around two degrees. Other cities paint roofs white so that they reflect sunlight instead of absorbing it.\n\nHowever, experts warn that trees need years to grow and must be looked after. Planting them is the easy part; making sure they survive is much harder. A green corridor that is forgotten after the opening ceremony will not cool anyone.","svg":null,"table":null}'::jsonb, 'What is an "urban heat island"?', '[{"label":"A","text":"A park in the middle of a large city.","is_correct":false,"distractor_type":"Confunde el problema con una solución.","explanation_feedback":"Incorrecta. Los parques y árboles son parte de la solución, no el fenómeno."},{"label":"B","text":"A factory that produces a lot of heat.","is_correct":false,"distractor_type":"Toma una causa como definición.","explanation_feedback":"Incorrecta. Las fábricas aportan calor, pero el término describe toda la zona urbana."},{"label":"C","text":"A city area that is warmer than the land around it.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Es la zona urbana que llega a estar varios grados más caliente que el campo alrededor."},{"label":"D","text":"An island near the coast with very hot weather.","is_correct":false,"distractor_type":"Interpreta «island» literalmente.","explanation_feedback":"Incorrecta. No es una isla geográfica; es una zona de la ciudad más caliente."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 90, 'original_generated'
from public.evidences e where e.code = 'IN.E6'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '183a4b80-0ed6-5526-9030-d60b95333ea8', e.id, 'IN', (select id from public.content_components where code = 'IN.P6'), 'qa_passed', 'cefr_part', '{"title":"Cooler cities","text":"On a sunny afternoon, the centre of a large city can be several degrees hotter than the countryside around it. Scientists call this an \"urban heat island\". It happens because materials like concrete and asphalt absorb heat during the day and release it slowly at night. Cars, air conditioners and factories add even more heat.\n\nThis is not just a question of comfort. Very high temperatures can be dangerous for older people and small children, and they increase the amount of electricity a city uses. In some places, hot nights also make the air more polluted.\n\nCities around the world are trying different solutions. Medellín, for example, created a network of \"green corridors\" by planting trees and plants along roads and streams. Officials say temperatures in some of those areas have fallen by around two degrees. Other cities paint roofs white so that they reflect sunlight instead of absorbing it.\n\nHowever, experts warn that trees need years to grow and must be looked after. Planting them is the easy part; making sure they survive is much harder. A green corridor that is forgotten after the opening ceremony will not cool anyone.","svg":null,"table":null}'::jsonb, 'Why do concrete and asphalt make cities hotter?', '[{"label":"A","text":"They are darker than most trees and plants.","is_correct":false,"distractor_type":"Supone una razón no explicada en el texto.","explanation_feedback":"Incorrecta. El texto explica la absorción y liberación del calor, no el color."},{"label":"B","text":"They keep heat from the day and give it off at night.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Absorben calor de día y lo liberan despacio de noche."},{"label":"C","text":"They produce electricity for air conditioners.","is_correct":false,"distractor_type":"Mezcla dos causas distintas.","explanation_feedback":"Incorrecta. El concreto no produce electricidad."},{"label":"D","text":"They stop cars from moving quickly.","is_correct":false,"distractor_type":"Inventa una relación.","explanation_feedback":"Incorrecta. El texto no relaciona el concreto con la velocidad de los carros."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 90, 'original_generated'
from public.evidences e where e.code = 'IN.E6'
on conflict (id) do nothing;
