select '03b18cc0-e373-5f82-a7c2-22fdbde7b3cc', e.id, 'IN', (select id from public.content_components where code = 'IN.P6'), 'qa_passed', 'cefr_part', '{"title":"Cooler cities","text":"On a sunny afternoon, the centre of a large city can be several degrees hotter than the countryside around it. Scientists call this an \"urban heat island\". It happens because materials like concrete and asphalt absorb heat during the day and release it slowly at night. Cars, air conditioners and factories add even more heat.\n\nThis is not just a question of comfort. Very high temperatures can be dangerous for older people and small children, and they increase the amount of electricity a city uses. In some places, hot nights also make the air more polluted.\n\nCities around the world are trying different solutions. Medellín, for example, created a network of \"green corridors\" by planting trees and plants along roads and streams. Officials say temperatures in some of those areas have fallen by around two degrees. Other cities paint roofs white so that they reflect sunlight instead of absorbing it.\n\nHowever, experts warn that trees need years to grow and must be looked after. Planting them is the easy part; making sure they survive is much harder. A green corridor that is forgotten after the opening ceremony will not cool anyone.","svg":null,"table":null}'::jsonb, 'What is the purpose of painting roofs white?', '[{"label":"A","text":"To reflect sunlight so buildings absorb less heat.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Los techos blancos reflejan la luz del sol en lugar de absorberla."},{"label":"B","text":"To make the city more attractive to tourists.","is_correct":false,"distractor_type":"Supone un propósito estético.","explanation_feedback":"Incorrecta. El texto da una razón térmica, no estética."},{"label":"C","text":"To show where the green corridors are.","is_correct":false,"distractor_type":"Mezcla dos soluciones.","explanation_feedback":"Incorrecta. Los techos blancos y los corredores verdes son medidas distintas."},{"label":"D","text":"To protect the roofs from heavy rain.","is_correct":false,"distractor_type":"Inventa un propósito.","explanation_feedback":"Incorrecta. El texto no menciona la lluvia."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 90, 'original_generated'
