insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'dab06a03-19a5-5828-bd1b-6a2126a2b59d', e.id, 'IN', (select id from public.content_components where code = 'IN.P6'), 'qa_passed', 'cefr_part', '{"title":"Cooler cities","text":"On a sunny afternoon, the centre of a large city can be several degrees hotter than the countryside around it. Scientists call this an \"urban heat island\". It happens because materials like concrete and asphalt absorb heat during the day and release it slowly at night. Cars, air conditioners and factories add even more heat.\n\nThis is not just a question of comfort. Very high temperatures can be dangerous for older people and small children, and they increase the amount of electricity a city uses. In some places, hot nights also make the air more polluted.\n\nCities around the world are trying different solutions. Medellín, for example, created a network of \"green corridors\" by planting trees and plants along roads and streams. Officials say temperatures in some of those areas have fallen by around two degrees. Other cities paint roofs white so that they reflect sunlight instead of absorbing it.\n\nHowever, experts warn that trees need years to grow and must be looked after. Planting them is the easy part; making sure they survive is much harder. A green corridor that is forgotten after the opening ceremony will not cool anyone.","svg":null,"table":null}'::jsonb, 'What does the writer mean in the last sentence?', '[{"label":"A","text":"Trees cannot cool cities at all.","is_correct":false,"distractor_type":"Generaliza la advertencia.","explanation_feedback":"Incorrecta. El texto dice que sí ayudan, si se cuidan."},{"label":"B","text":"Green projects only work if they are maintained.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Un corredor verde olvidado tras su inauguración no refrescará a nadie: hay que mantenerlo."},{"label":"C","text":"Opening ceremonies should not be organised.","is_correct":false,"distractor_type":"Toma la ceremonia como el problema.","explanation_feedback":"Incorrecta. La crítica es al abandono posterior, no a la ceremonia."},{"label":"D","text":"People forget to visit green corridors.","is_correct":false,"distractor_type":"Interpreta «forgotten» como falta de visitantes.","explanation_feedback":"Incorrecta. «Forgotten» aquí significa descuidado, sin mantenimiento."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 90, 'original_generated'
from public.evidences e where e.code = 'IN.E6'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'e81726aa-b85d-57e4-b5f3-c80a22dcdf1d', e.id, 'IN', (select id from public.content_components where code = 'IN.P6'), 'qa_passed', 'cefr_part', '{"title":"Water for Uribia","text":"When Laura Pushaina finished her engineering degree in Barranquilla, most of her classmates took jobs in big companies. Laura went back to Uribia, in La Guajira, where she grew up. \"In my community, children walk for hours to collect water that is often not safe to drink,\" she explains. \"I studied engineering because I wanted to change that.\"\n\nWith a small team of volunteers, Laura designed a system that collects rainwater from the roofs of schools and stores it in large tanks. Because it doesn''t rain often in La Guajira, every drop matters, so the system also includes simple filters made with sand and charcoal. The first tank was installed at a primary school three years ago. Today there are eleven.\n\nThe project has not been easy. At the beginning, some families did not trust the water, and two tanks were damaged during a storm. Laura decided to train local young people to repair and clean the systems themselves. \"If the community doesn''t own the project, it will die when we leave,\" she says. Now a group of fifteen teenagers looks after the tanks, and some of them are planning to study engineering too.","svg":null,"table":null}'::jsonb, 'Why did Laura return to Uribia?', '[{"label":"A","text":"She wanted to solve a water problem in her community.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Volvió porque estudió ingeniería para cambiar la falta de agua potable en su comunidad."},{"label":"B","text":"Her university was in Uribia.","is_correct":false,"distractor_type":"Confunde el lugar de estudio.","explanation_feedback":"Incorrecta. Estudió en Barranquilla."},{"label":"C","text":"She could not find a job in a big company.","is_correct":false,"distractor_type":"Supone una razón que el texto no da.","explanation_feedback":"Incorrecta. Fueron sus compañeros quienes tomaron esos empleos; no dice que ella no consiguiera uno."},{"label":"D","text":"Her family asked her to come back.","is_correct":false,"distractor_type":"Inventa una razón.","explanation_feedback":"Incorrecta. El texto no menciona una petición de su familia."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 90, 'original_generated'
from public.evidences e where e.code = 'IN.E6'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '2caae53a-f538-5654-b066-53e30f60385b', e.id, 'IN', (select id from public.content_components where code = 'IN.P6'), 'qa_passed', 'cefr_part', '{"title":"Water for Uribia","text":"When Laura Pushaina finished her engineering degree in Barranquilla, most of her classmates took jobs in big companies. Laura went back to Uribia, in La Guajira, where she grew up. \"In my community, children walk for hours to collect water that is often not safe to drink,\" she explains. \"I studied engineering because I wanted to change that.\"\n\nWith a small team of volunteers, Laura designed a system that collects rainwater from the roofs of schools and stores it in large tanks. Because it doesn''t rain often in La Guajira, every drop matters, so the system also includes simple filters made with sand and charcoal. The first tank was installed at a primary school three years ago. Today there are eleven.\n\nThe project has not been easy. At the beginning, some families did not trust the water, and two tanks were damaged during a storm. Laura decided to train local young people to repair and clean the systems themselves. \"If the community doesn''t own the project, it will die when we leave,\" she says. Now a group of fifteen teenagers looks after the tanks, and some of them are planning to study engineering too.","svg":null,"table":null}'::jsonb, 'Why are filters part of the system?', '[{"label":"A","text":"To protect the tanks during storms.","is_correct":false,"distractor_type":"Relaciona los filtros con la tormenta.","explanation_feedback":"Incorrecta. Los tanques dañados no tienen relación con los filtros."},{"label":"B","text":"To make the collected rainwater safe to drink.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Los filtros de arena y carbón ayudan a que el agua sea segura."},{"label":"C","text":"To collect more rain from the roofs.","is_correct":false,"distractor_type":"Confunde filtrar con recoger.","explanation_feedback":"Incorrecta. Los techos recogen el agua; los filtros la limpian."},{"label":"D","text":"To make it rain more often.","is_correct":false,"distractor_type":"Interpreta mal «every drop matters».","explanation_feedback":"Incorrecta. Los filtros no cambian la cantidad de lluvia."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 90, 'original_generated'
from public.evidences e where e.code = 'IN.E6'
