select '8d040084-fe02-5c00-8ad9-289667880862', e.id, 'IN', (select id from public.content_components where code = 'IN.P6'), 'qa_passed', 'cefr_part', '{"title":"Water for Uribia","text":"When Laura Pushaina finished her engineering degree in Barranquilla, most of her classmates took jobs in big companies. Laura went back to Uribia, in La Guajira, where she grew up. \"In my community, children walk for hours to collect water that is often not safe to drink,\" she explains. \"I studied engineering because I wanted to change that.\"\n\nWith a small team of volunteers, Laura designed a system that collects rainwater from the roofs of schools and stores it in large tanks. Because it doesn''t rain often in La Guajira, every drop matters, so the system also includes simple filters made with sand and charcoal. The first tank was installed at a primary school three years ago. Today there are eleven.\n\nThe project has not been easy. At the beginning, some families did not trust the water, and two tanks were damaged during a storm. Laura decided to train local young people to repair and clean the systems themselves. \"If the community doesn''t own the project, it will die when we leave,\" she says. Now a group of fifteen teenagers looks after the tanks, and some of them are planning to study engineering too.","svg":null,"table":null}'::jsonb, 'Which problem did the project have at the start?', '[{"label":"A","text":"Some people did not believe the water was good.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Algunas familias no confiaban en el agua al comienzo."},{"label":"B","text":"There were not enough volunteers.","is_correct":false,"distractor_type":"Inventa un problema.","explanation_feedback":"Incorrecta. El texto no dice que faltaran voluntarios."},{"label":"C","text":"The water was too expensive.","is_correct":false,"distractor_type":"Inventa un costo.","explanation_feedback":"Incorrecta. El texto no habla del precio del agua."},{"label":"D","text":"The schools refused to have tanks.","is_correct":false,"distractor_type":"Inventa una negativa.","explanation_feedback":"Incorrecta. Las escuelas recibieron los tanques; quienes desconfiaban eran algunas familias."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 90, 'original_generated'
