select '48b31512-621b-5a6d-8efc-37a1eff75756', e.id, 'IN', (select id from public.content_components where code = 'IN.P6'), 'qa_passed', 'cefr_part', '{"title":"Water for Uribia","text":"When Laura Pushaina finished her engineering degree in Barranquilla, most of her classmates took jobs in big companies. Laura went back to Uribia, in La Guajira, where she grew up. \"In my community, children walk for hours to collect water that is often not safe to drink,\" she explains. \"I studied engineering because I wanted to change that.\"\n\nWith a small team of volunteers, Laura designed a system that collects rainwater from the roofs of schools and stores it in large tanks. Because it doesn''t rain often in La Guajira, every drop matters, so the system also includes simple filters made with sand and charcoal. The first tank was installed at a primary school three years ago. Today there are eleven.\n\nThe project has not been easy. At the beginning, some families did not trust the water, and two tanks were damaged during a storm. Laura decided to train local young people to repair and clean the systems themselves. \"If the community doesn''t own the project, it will die when we leave,\" she says. Now a group of fifteen teenagers looks after the tanks, and some of them are planning to study engineering too.","svg":null,"table":null}'::jsonb, 'Why did Laura train young people from the community?', '[{"label":"A","text":"Because the volunteers were too expensive.","is_correct":false,"distractor_type":"Inventa una razón económica.","explanation_feedback":"Incorrecta. El texto no menciona costos de los voluntarios."},{"label":"B","text":"Because the storm destroyed all the tanks.","is_correct":false,"distractor_type":"Exagera el daño.","explanation_feedback":"Incorrecta. Solo dos tanques se dañaron, y la razón fue la sostenibilidad."},{"label":"C","text":"So the project could continue without her team.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Ella dice que si la comunidad no se apropia del proyecto, morirá cuando ellos se vayan."},{"label":"D","text":"Because they wanted to study in Barranquilla.","is_correct":false,"distractor_type":"Toma una consecuencia como causa.","explanation_feedback":"Incorrecta. Algunos ahora quieren estudiar ingeniería, pero esa no fue la razón para entrenarlos."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 90, 'original_generated'
