insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '115b468a-9545-5fa2-96d4-c70a16a73e2d', e.id, 'IN', (select id from public.content_components where code = 'IN.P6'), 'qa_passed', 'cefr_part', '{"title":"Are video games a waste of time?","text":"Many parents worry when their teenage children spend hours playing video games. They fear games make young people lazy, violent or unable to concentrate. But research on the subject suggests the picture is more complicated.\n\nSome studies have found that certain action games can improve attention and the ability to react quickly. Strategy and puzzle games may help players plan and solve problems. Online games that require teamwork can also build communication skills, especially when players have to coordinate with people they have never met.\n\nThat does not mean all gaming is good. Playing late at night can reduce sleep, and lack of sleep affects memory and mood. Some games are designed to keep players spending money on small extras, which can become a problem. And for a small number of people, gaming becomes an addiction that damages their studies and relationships.\n\nMost experts agree that the key is balance. Instead of banning games completely, they recommend that families agree on clear limits, keep screens out of bedrooms at night, and pay attention to the type of games, not only the number of hours. As one psychologist puts it, \"Two hours of building a city with friends is not the same as two hours alone at three in the morning.\"","svg":null,"table":null}'::jsonb, 'What is the writer''s opinion in the first paragraph?', '[{"label":"A","text":"Parents should play more games with children.","is_correct":false,"distractor_type":"Inventa una recomendación.","explanation_feedback":"Incorrecta. El primer párrafo no recomienda eso."},{"label":"B","text":"Teenagers don''t play as much as people say.","is_correct":false,"distractor_type":"Inventa una afirmación.","explanation_feedback":"Incorrecta. El autor no discute cuánto juegan."},{"label":"C","text":"The effects of games are not as simple as many parents think.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Dice que la investigación sugiere que el panorama «is more complicated»."},{"label":"D","text":"Video games always make teenagers violent.","is_correct":false,"distractor_type":"Toma el temor de los padres como opinión del autor.","explanation_feedback":"Incorrecta. El autor presenta ese temor para matizarlo."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 90, 'original_generated'
from public.evidences e where e.code = 'IN.E6'
on conflict (id) do nothing;
insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select '8f2e82e0-06c6-598c-a23a-02862f1c3d09', e.id, 'IN', (select id from public.content_components where code = 'IN.P6'), 'qa_passed', 'cefr_part', '{"title":"Are video games a waste of time?","text":"Many parents worry when their teenage children spend hours playing video games. They fear games make young people lazy, violent or unable to concentrate. But research on the subject suggests the picture is more complicated.\n\nSome studies have found that certain action games can improve attention and the ability to react quickly. Strategy and puzzle games may help players plan and solve problems. Online games that require teamwork can also build communication skills, especially when players have to coordinate with people they have never met.\n\nThat does not mean all gaming is good. Playing late at night can reduce sleep, and lack of sleep affects memory and mood. Some games are designed to keep players spending money on small extras, which can become a problem. And for a small number of people, gaming becomes an addiction that damages their studies and relationships.\n\nMost experts agree that the key is balance. Instead of banning games completely, they recommend that families agree on clear limits, keep screens out of bedrooms at night, and pay attention to the type of games, not only the number of hours. As one psychologist puts it, \"Two hours of building a city with friends is not the same as two hours alone at three in the morning.\"","svg":null,"table":null}'::jsonb, 'According to the text, what can strategy and puzzle games help with?', '[{"label":"A","text":"Making friends in other countries.","is_correct":false,"distractor_type":"Atribuye el efecto de los juegos en línea en equipo.","explanation_feedback":"Incorrecta. La comunicación se asocia a los juegos en línea en equipo."},{"label":"B","text":"Reacting faster to images.","is_correct":false,"distractor_type":"Atribuye a estos juegos el efecto de los de acción.","explanation_feedback":"Incorrecta. La reacción rápida se asocia a ciertos juegos de acción."},{"label":"C","text":"Sleeping better at night.","is_correct":false,"distractor_type":"Contradice el texto.","explanation_feedback":"Incorrecta. El texto dice que jugar de noche puede reducir el sueño."},{"label":"D","text":"Planning and solving problems.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Dice que «may help players plan and solve problems»."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 90, 'original_generated'
