select 'a08d03f8-6de8-5627-b40f-2d4c7ff4d248', e.id, 'IN', (select id from public.content_components where code = 'IN.P6'), 'qa_passed', 'cefr_part', '{"title":"Are video games a waste of time?","text":"Many parents worry when their teenage children spend hours playing video games. They fear games make young people lazy, violent or unable to concentrate. But research on the subject suggests the picture is more complicated.\n\nSome studies have found that certain action games can improve attention and the ability to react quickly. Strategy and puzzle games may help players plan and solve problems. Online games that require teamwork can also build communication skills, especially when players have to coordinate with people they have never met.\n\nThat does not mean all gaming is good. Playing late at night can reduce sleep, and lack of sleep affects memory and mood. Some games are designed to keep players spending money on small extras, which can become a problem. And for a small number of people, gaming becomes an addiction that damages their studies and relationships.\n\nMost experts agree that the key is balance. Instead of banning games completely, they recommend that families agree on clear limits, keep screens out of bedrooms at night, and pay attention to the type of games, not only the number of hours. As one psychologist puts it, \"Two hours of building a city with friends is not the same as two hours alone at three in the morning.\"","svg":null,"table":null}'::jsonb, 'Why does the writer mention money?', '[{"label":"A","text":"Some games push players to keep buying extras.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Algunos juegos están diseñados para que los jugadores sigan gastando en pequeños extras."},{"label":"B","text":"Good games are usually very expensive.","is_correct":false,"distractor_type":"Inventa una relación precio-calidad.","explanation_feedback":"Incorrecta. El texto no habla del precio de los juegos."},{"label":"C","text":"Parents should not pay for video games.","is_correct":false,"distractor_type":"Inventa una recomendación.","explanation_feedback":"Incorrecta. El texto no dice eso."},{"label":"D","text":"Gamers can earn a lot by playing online.","is_correct":false,"distractor_type":"Invierte la dirección del dinero.","explanation_feedback":"Incorrecta. El texto habla de gastar, no de ganar."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 90, 'original_generated'
