insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'f95cf323-5061-5ed9-9d43-897d56e2e7f2', e.id, 'IN', (select id from public.content_components where code = 'IN.P6'), 'qa_passed', 'cefr_part', '{"title":"Are video games a waste of time?","text":"Many parents worry when their teenage children spend hours playing video games. They fear games make young people lazy, violent or unable to concentrate. But research on the subject suggests the picture is more complicated.\n\nSome studies have found that certain action games can improve attention and the ability to react quickly. Strategy and puzzle games may help players plan and solve problems. Online games that require teamwork can also build communication skills, especially when players have to coordinate with people they have never met.\n\nThat does not mean all gaming is good. Playing late at night can reduce sleep, and lack of sleep affects memory and mood. Some games are designed to keep players spending money on small extras, which can become a problem. And for a small number of people, gaming becomes an addiction that damages their studies and relationships.\n\nMost experts agree that the key is balance. Instead of banning games completely, they recommend that families agree on clear limits, keep screens out of bedrooms at night, and pay attention to the type of games, not only the number of hours. As one psychologist puts it, \"Two hours of building a city with friends is not the same as two hours alone at three in the morning.\"","svg":null,"table":null}'::jsonb, 'What do most experts recommend?', '[{"label":"A","text":"Banning video games completely at home.","is_correct":false,"distractor_type":"Contradice la recomendación.","explanation_feedback":"Incorrecta. Los expertos aconsejan no prohibirlos del todo."},{"label":"B","text":"Playing only between one and three a.m.","is_correct":false,"distractor_type":"Lee mal la cita del psicólogo.","explanation_feedback":"Incorrecta. La cita usa las tres de la mañana como ejemplo negativo."},{"label":"C","text":"Counting only the number of hours played.","is_correct":false,"distractor_type":"Contradice «not only the number of hours».","explanation_feedback":"Incorrecta. Piden fijarse también en el tipo de juego."},{"label":"D","text":"Setting limits and paying attention to the kind of games.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Recomiendan acordar límites, sacar las pantallas de la habitación de noche y fijarse en el tipo de juego."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 90, 'original_generated'
from public.evidences e where e.code = 'IN.E6'
