insert into public.questions (id, evidence_id, subject_id, component_id, status, context_type, context_content, stem, options, cefr_level, irt_a, irt_b, irt_c, estimated_time_seconds, origin)
select 'e0d12dfa-648a-50fe-b6cc-08007445a344', e.id, 'IN', (select id from public.content_components where code = 'IN.P6'), 'qa_passed', 'cefr_part', '{"title":"Are video games a waste of time?","text":"Many parents worry when their teenage children spend hours playing video games. They fear games make young people lazy, violent or unable to concentrate. But research on the subject suggests the picture is more complicated.\n\nSome studies have found that certain action games can improve attention and the ability to react quickly. Strategy and puzzle games may help players plan and solve problems. Online games that require teamwork can also build communication skills, especially when players have to coordinate with people they have never met.\n\nThat does not mean all gaming is good. Playing late at night can reduce sleep, and lack of sleep affects memory and mood. Some games are designed to keep players spending money on small extras, which can become a problem. And for a small number of people, gaming becomes an addiction that damages their studies and relationships.\n\nMost experts agree that the key is balance. Instead of banning games completely, they recommend that families agree on clear limits, keep screens out of bedrooms at night, and pay attention to the type of games, not only the number of hours. As one psychologist puts it, \"Two hours of building a city with friends is not the same as two hours alone at three in the morning.\"","svg":null,"table":null}'::jsonb, 'What is the psychologist''s point in the last sentence?', '[{"label":"A","text":"Building games are better than all other games.","is_correct":false,"distractor_type":"Generaliza el ejemplo.","explanation_feedback":"Incorrecta. El ejemplo ilustra una idea; no clasifica todos los juegos."},{"label":"B","text":"Playing with friends is always dangerous.","is_correct":false,"distractor_type":"Invierte el ejemplo.","explanation_feedback":"Incorrecta. Jugar con amigos aparece como el caso positivo."},{"label":"C","text":"How and when you play matters, not just how long.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Compara dos situaciones de igual duración para mostrar que el contexto cambia el efecto."},{"label":"D","text":"Teenagers should play for two hours every day.","is_correct":false,"distractor_type":"Toma la cifra como recomendación.","explanation_feedback":"Incorrecta. Las dos horas son parte de la comparación, no un consejo."}]'::jsonb, 'B1', 1.3, 1.3, 0.25, 90, 'original_generated'
